                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> FfiTrustDecision.AllowUnpairedForPairing
            3 -> FfiTrustDecision.Reject(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
