                4UL
                + FfiConverterString.allocationSize(value.`peerDeviceId`)
                + FfiConverterString.allocationSize(value.`peerFingerprint`)
            )
        }
        is FfiTrustDecision.AllowUnpairedForPairing -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiTrustDecision.Reject -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUShort.allocationSize(value.`httpStatus`)
                + FfiConverterString.allocationSize(value.`errorCode`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: FfiTrustDecision, buf: ByteBuffer) {
        when(value) {
            is FfiTrustDecision.Allow -> {
                buf.putInt(1)
